# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DOĞRUSAL REFERANS FONKSİYON f(x) = x VE DÖNÜŞÜMLERİ</text>\n  <rect x="25" y="42" width="310" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">REFERANS FONKSİYON: f(x) = x</text>\n  <line x1="60" y1="145" x2="295" y2="145" stroke="#475569" stroke-width="1.5"/>\n  <line x1="175" y1="75" x2="175" y2="215" stroke="#475569" stroke-width="1.5"/>\n  <line x1="105" y1="215" x2="245" y2="75" stroke="#2563eb" stroke-width="3"/>\n  <text x="252" y="88" font-size="11.5" font-weight="bold" fill="#1d4ed8">f(x) = x</text>\n  <line x1="125" y1="215" x2="215" y2="75" stroke="#16a34a" stroke-width="2.5" stroke-dasharray="4,3"/>\n  <text x="228" y="115" font-size="11" font-weight="bold" fill="#15803d">g(x) = 2x + 1</text>\n  <text x="182" y="158" font-size="10" fill="#334155">O(0,0)</text>\n  <text x="180" y="232" text-anchor="middle" font-size="11" fill="#1e3a8a">Tanım Kümesi: ℝ  |  Görüntü Kümesi: ℝ  |  Eğim: a = 1</text>\n  <rect x="350" y="42" width="325" height="200" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="512" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">TÜRETİLEN FONKSİYON: g(x) = a·f(x ± r) ± k</text>\n  <text x="366" y="92" font-size="11.5" font-weight="bold" fill="#78350f">• f(x) = x iken g(x) = a(x - r) + k = ax + b</text>\n  <text x="366" y="115" font-size="11.5" fill="#92400e">• Yatay Öteleme (r): f(x - r) → r birim sağa;</text>\n  <text x="376" y="131" font-size="11" fill="#92400e">f(x + r) → r birim sola ötelenir.</text>\n  <text x="366" y="153" font-size="11.5" fill="#92400e">• Düşey Öteleme (k): +k → k birim yukarı;</text>\n  <text x="376" y="169" font-size="11" fill="#92400e">-k → k birim aşağı ötelenir.</text>\n  <text x="366" y="191" font-size="11.5" fill="#92400e">• Katsayı / Eğim (a): Diklik ve artan-azalanlığı</text>\n  <text x="376" y="207" font-size="11" fill="#92400e">belirler; a &lt; 0 ise x eksenine göre yansıma olur.</text>\n  <text x="512" y="229" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Değişim Oranı (Eğim): m = a = Δy / Δx = [g(x₂)-g(x₁)] / (x₂-x₁)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">NİTEL ÖZELLİKLER: ARTANLIK-AZALANLIK, SIFIR (KÖK) VE İŞARET</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">EĞİM (a) VE ARTANLIK - AZALANLIK</text>\n  <rect x="40" y="78" width="285" height="65" rx="6" fill="#ffffff" stroke="#86efac"/>\n  <text x="50" y="98" font-size="12" font-weight="bold" fill="#15803d">• a &gt; 0 ise ARTAN Fonksiyon:</text>\n  <text x="50" y="116" font-size="11" fill="#14532d">x₁ &lt; x₂ iken g(x₁) &lt; g(x₂) olur. Grafik soldan</text>\n  <text x="50" y="132" font-size="11" fill="#14532d">sağa yukarı yükselir (Örn: g(x) = 3x - 6).</text>\n  <rect x="40" y="152" width="285" height="72" rx="6" fill="#ffffff" stroke="#86efac"/>\n  <text x="50" y="172" font-size="12" font-weight="bold" fill="#dc2626">• a &lt; 0 ise AZALAN Fonksiyon:</text>\n  <text x="50" y="190" font-size="11" fill="#14532d">x₁ &lt; x₂ iken g(x₁) &gt; g(x₂) olur. Grafik soldan</text>\n  <text x="50" y="206" font-size="11" fill="#14532d">sağa aşağı iner (Örn: g(x) = -2x + 8).</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">FONKSİYONUN SIFIRI (KÖKÜ) VE İŞARETİ</text>\n  <text x="370" y="92" font-size="11.5" font-weight="bold" fill="#581c87">• Fonksiyonun Sıfırı (x eksenini kestiği nokta):</text>\n  <text x="378" y="110" font-size="11.5" fill="#6b21a8">g(x) = ax + b = 0  ⇒  x₀ = -b / a</text>\n  <text x="370" y="134" font-size="11.5" font-weight="bold" fill="#581c87">• y Eksenini Kestiği Nokta (x = 0 için):</text>\n  <text x="378" y="152" font-size="11.5" fill="#6b21a8">g(0) = b  ⇒  (0, b) noktası</text>\n  <rect x="370" y="164" width="290" height="64" rx="6" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="515" y="183" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">İşaret İncelemesi (a &gt; 0 ise):</text>\n  <text x="515" y="201" text-anchor="middle" font-size="11" fill="#581c87">x &gt; -b/a aralığında g(x) &gt; 0 (Pozitif, x ekseni üstü)</text>\n  <text x="515" y="218" text-anchor="middle" font-size="11" fill="#581c87">x &lt; -b/a aralığında g(x) &lt; 0 (Negatif, x ekseni altı)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TANIM ARALIĞI, MAKSİMUM-MİNİMUM VE BİRE BİR-ÖRTENLİK</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">BİRE BİRLİK VE MAKSİMUM-MİNİMUM</text>\n  <text x="40" y="92" font-size="11.5" font-weight="bold" fill="#7c2d12">• Gerçek Sayılarda (g: ℝ → ℝ, a ≠ 0):</text>\n  <text x="48" y="110" font-size="11" fill="#9a3412">- Her farklı x\'in görüntüsü farklıdır → BİRE BİR.</text>\n  <text x="48" y="126" font-size="11" fill="#9a3412">- Görüntü kümesi tüm ℝ\'dir → ÖRTEN.</text>\n  <text x="48" y="142" font-size="11" font-weight="bold" fill="#c2410c">- Tanım kümesi ℝ iken max ve min değeri YOKTUR.</text>\n  <text x="40" y="168" font-size="11.5" font-weight="bold" fill="#7c2d12">• Kapalı Aralıkta Tanımlı İse (g: [m, n] → ℝ):</text>\n  <text x="48" y="186" font-size="11" fill="#9a3412">- a &gt; 0 (artan) ise: Min = g(m),  Max = g(n)</text>\n  <text x="48" y="204" font-size="11" fill="#9a3412">- a &lt; 0 (azalan) ise: Max = g(m),  Min = g(n)</text>\n  <text x="48" y="222" font-size="10.5" fill="#7c2d12">Görüntü kümesi de kapalı bir aralık olur.</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">GERÇEK YAŞAM MODELLEMESİ</text>\n  <rect x="372" y="80" width="286" height="58" rx="6" fill="#ffffff" stroke="#67e8f9"/>\n  <text x="515" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">Genel Model:  g(x) = a·x + b</text>\n  <text x="515" y="122" text-anchor="middle" font-size="11" fill="#164e63">b: Başlangıç değeri (x = 0)  |  a: Birim değişim oranı</text>\n  <text x="372" y="158" font-size="11" fill="#155e75">• Örnek 1 (Kumbara): Başlangıçta 120 TL olan ve her</text>\n  <text x="380" y="174" font-size="11" font-weight="bold" fill="#0e7490">gün 30 TL eklenen kumbara → g(x) = 30x + 120</text>\n  <text x="372" y="198" font-size="11" fill="#155e75">• Örnek 2 (Su Deposu): 500 L su bulunan ve dakikada</text>\n  <text x="380" y="214" font-size="11" font-weight="bold" fill="#0e7490">25 L boşalan depo → g(x) = 500 - 25x (Sıfırı: x = 20 dk)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
